//! Parity test against the original Python implementation.
//!
//! `tests/fixtures/golden.json` is generated by `gen_golden.py` from the same
//! `assets/allconf.yml` snapshot. Conferences that use the `PT` timezone are
//! compared separately: Python rejects `PT` (the deadline is silently dropped),
//! Rust resolves it, so those rows are an intentional, verified divergence.

use std::collections::BTreeSet;

use chrono::{DateTime, Duration, Utc};
use ccfddl_tui::data::{ConferenceRow, DataService, Favorites, query};
use ccfddl_tui::format::format_duration;
use serde_json::Value;

const GOLDEN: &str = include_str!("fixtures/golden.json");

fn golden() -> Value {
    serde_json::from_str(GOLDEN).expect("golden.json is valid JSON")
}

fn now(golden: &Value) -> DateTime<Utc> {
    DateTime::parse_from_rfc3339(golden["now"].as_str().unwrap())
        .unwrap()
        .with_timezone(&Utc)
}

fn key(row: &ConferenceRow) -> String {
    format!("{}_{}", row.title, row.year)
}

fn rust_rows(now: DateTime<Utc>) -> Vec<ConferenceRow> {
    let dir = tempfile::tempdir().unwrap();
    let mut service = DataService::with_paths(
        None,
        dir.path().join("cache.yml"),
        Favorites::empty_at(dir.path().join("fav.json")),
    );
    service
        .load_conferences_with(|| Err(ccfddl_tui::data::DataError::Remote("offline".into())))
        .unwrap();
    service.process_rows(now)
}

/// Titles of conferences that have at least one edition using the `PT` timezone.
fn pt_titles() -> BTreeSet<String> {
    let mut titles = BTreeSet::new();
    let mut current = String::new();
    for line in ccfddl_tui::data::source::EMBEDDED_YAML.lines() {
        if let Some(title) = line.strip_prefix("- title: ") {
            current = title.trim().trim_matches('\'').trim_matches('"').to_string();
        } else if line.trim() == "timezone: PT" {
            titles.insert(current.clone());
        }
    }
    titles
}

fn opt_str(v: &Value) -> Option<String> {
    v.as_str().map(str::to_owned)
}

#[test]
fn rows_match_python_except_pt_conferences() {
    let golden = golden();
    let now = now(&golden);
    let pt = pt_titles();
    assert!(pt.len() >= 5, "expected several PT conferences, got {pt:?}");

    // Both sides emit one row per conference, in snapshot order. Titles are not
    // unique (SEC and FSE each appear twice), so compare by position.
    let rust = rust_rows(now);
    let python = golden["rows_unsorted"].as_array().unwrap();
    assert_eq!(rust.len(), python.len(), "row counts differ");

    let mut compared = 0;
    for (row, py) in rust.iter().zip(python) {
        let title = py["title"].as_str().unwrap();
        assert_eq!(row.title, title, "row order diverged");
        if pt.contains(title) {
            continue;
        }
        let ctx = format!("{title} {}", py["year"]);

        assert_eq!(row.year as i64, py["year"].as_i64().unwrap(), "{ctx} year");
        assert_eq!(row.sub, py["sub"].as_str().unwrap(), "{ctx} sub");
        assert_eq!(row.rank, py["rank"].as_str().unwrap(), "{ctx} rank");
        assert_eq!(row.core_rank, opt_str(&py["core_rank"]), "{ctx} core");
        assert_eq!(row.thcpl_rank, opt_str(&py["thcpl_rank"]), "{ctx} thcpl");
        assert_eq!(row.countdown, py["countdown"].as_str().unwrap(), "{ctx} countdown");
        assert_eq!(row.place, py["place"].as_str().unwrap(), "{ctx} place");
        assert_eq!(row.date, py["date"].as_str().unwrap(), "{ctx} date");
        assert_eq!(row.link, py["link"].as_str().unwrap(), "{ctx} link");
        assert_eq!(row.is_running, py["is_running"].as_bool().unwrap(), "{ctx} running");
        assert_eq!(row.is_tbd, py["is_tbd"].as_bool().unwrap(), "{ctx} tbd");
        assert_eq!(row.is_expired, py["is_expired"].as_bool().unwrap(), "{ctx} expired");

        let expected_deadline = py["deadline"]
            .as_str()
            .map(|s| DateTime::parse_from_rfc3339(s).unwrap().with_timezone(&Utc));
        assert_eq!(row.deadline, expected_deadline, "{ctx} deadline");
        compared += 1;
    }

    assert!(compared > 300, "only compared {compared} rows");
}

#[test]
fn pt_conferences_now_resolve_where_python_dropped_them() {
    let golden = golden();
    let now = now(&golden);
    let pt = pt_titles();
    let rust = rust_rows(now);

    let python = golden["rows_unsorted"].as_array().unwrap();

    let mut improved = 0;
    for (row, py) in rust.iter().zip(python).filter(|(r, _)| pt.contains(&r.title)) {
        // Python can only ever report fewer valid deadlines for these entries.
        if py["deadline"].is_null() && row.deadline.is_some() {
            improved += 1;
        }
    }
    assert!(improved > 0, "expected PT to turn at least one N/A row into a dated row");
}

#[test]
fn sorted_order_matches_python_for_non_pt_rows() {
    let golden = golden();
    let pt = pt_titles();
    let sorted = query::sort_rows(rust_rows(now(&golden)));

    let keep = |keys: Vec<String>| -> Vec<String> {
        keys.into_iter()
            .filter(|k| !pt.iter().any(|t| k.strip_prefix(t.as_str()).is_some_and(|rest| rest.starts_with('_'))))
            .collect()
    };
    let rust_keys = keep(sorted.iter().map(key).collect());
    let python_keys = keep(
        golden["rows_sorted_keys"]
            .as_array()
            .unwrap()
            .iter()
            .map(|k| k.as_str().unwrap().to_string())
            .collect(),
    );
    assert!(python_keys.len() > 300);
    assert_eq!(rust_keys, python_keys);
}

#[test]
fn fuzzy_search_matches_python() {
    let golden = golden();
    let pt = pt_titles();
    let rows = rust_rows(now(&golden));

    let keep = |keys: Vec<String>| -> Vec<String> {
        keys.into_iter()
            .filter(|k| !pt.iter().any(|t| k.strip_prefix(t.as_str()).is_some_and(|rest| rest.starts_with('_'))))
            .collect()
    };

    let searches = golden["searches"].as_object().unwrap();
    assert!(searches.len() >= 8);
    for (q, expected) in searches {
        let expected: Vec<String> = expected
            .as_array()
            .unwrap()
            .iter()
            .map(|k| k.as_str().unwrap().to_string())
            .collect();
        let actual: Vec<String> = query::fuzzy_search(rows.clone(), q).iter().map(key).collect();
        assert_eq!(keep(actual), keep(expected), "query {q:?}");
    }
}

#[test]
fn format_duration_matches_python() {
    let golden = golden();
    let now = now(&golden);
    let durations = golden["durations"].as_array().unwrap();
    assert!(durations.len() >= 10);
    for pair in durations {
        let secs = pair[0].as_i64().unwrap();
        let expected = pair[1].as_str().unwrap();
        assert_eq!(format_duration(now + Duration::seconds(secs), now), expected, "{secs}s");
    }
}
